export function createOptimisticStore(initialState) {
  let base = initialState;
  let visible = initialState;
  let pending = new Map();
  const subscriptions = new Set();

  function recompute(nextBase, changes) {
    let state = nextBase;
    for (const update of changes.values()) {
      state = update(state);
    }
    return state;
  }

  function notify() {
    // Snapshot subscriptions so unsubscription cannot disrupt this notification.
    for (const { listener } of Array.from(subscriptions)) {
      try {
        listener();
      } catch {
        // Continue notifying the remaining listeners.
      }
    }
  }

  return {
    getState() {
      return visible;
    },

    apply(id, update) {
      if (pending.has(id)) {
        throw new Error("A change with this id is already pending.");
      }

      const nextVisible = update(visible);
      pending.set(id, update);
      visible = nextVisible;
      notify();
    },

    confirm(id) {
      if (!pending.has(id)) {
        return false;
      }

      const update = pending.get(id);
      const remaining = new Map(pending);
      remaining.delete(id);

      const nextBase = update(base);
      const nextVisible = recompute(nextBase, remaining);

      base = nextBase;
      pending = remaining;
      visible = nextVisible;
      notify();
      return true;
    },

    rollback(id) {
      if (!pending.has(id)) {
        return false;
      }

      const remaining = new Map(pending);
      remaining.delete(id);
      const nextVisible = recompute(base, remaining);

      pending = remaining;
      visible = nextVisible;
      notify();
      return true;
    },

    subscribe(listener) {
      const subscription = { listener };
      subscriptions.add(subscription);

      return function unsubscribe() {
        subscriptions.delete(subscription);
      };
    },
  };
}
